#!/usr/bin/env bash
# Fail when the iOS host Info.plist lacks keys Compose Multiplatform needs at launch (PlistSanityCheck).
# Usage: scripts/check-ios-plist.sh [plist]   (default: iosApp/iosApp/Info.plist, as regenerated by xcodegen)
set -euo pipefail
plist="${1:-$(cd "$(dirname "$0")/.." && pwd)/iosApp/iosApp/Info.plist}"
v=$(plutil -extract CADisableMinimumFrameDurationOnPhone raw -o - "$plist" 2>/dev/null || true)
[ "$v" = "true" ] || { echo "FAIL: $plist needs CADisableMinimumFrameDurationOnPhone = true" >&2; exit 1; }
echo "ok: $plist"
